import unittest

from reports.export import export_csv


class ExportCsvTests(unittest.TestCase):
    def test_basic(self):
        out = export_csv(
            [{"a": 1, "b": "x"}, {"a": 2, "b": "y"}],
            ["a", "b"],
        )
        self.assertEqual(out, "a,b\r\n1,x\r\n2,y\r\n")

    def test_empty_rows(self):
        self.assertEqual(export_csv([], ["a", "b"]), "a,b\r\n")

    def test_empty_columns(self):
        self.assertEqual(export_csv([{"a": 1}], []), "\r\n")
        self.assertEqual(export_csv([], []), "\r\n")

    def test_missing_and_none(self):
        out = export_csv([{"a": None}, {}], ["a", "b"])
        self.assertEqual(out, "a,b\r\n,\r\n,\r\n")

    def test_quoting(self):
        out = export_csv(
            [{"a": 'he said "hi"', "b": "x,y", "c": "line1\nline2\r\nend"}],
            ["a", "b", "c"],
        )
        self.assertEqual(
            out,
            'a,b,c\r\n"he said ""hi""","x,y","line1\nline2\r\nend"\r\n',
        )

    def test_unicode_and_str_conversion(self):
        out = export_csv([{"a": "caf\u00e9", "b": 3.5}], ["a", "b"])
        self.assertEqual(out, "a,b\r\ncaf\u00e9,3.5\r\n")

    def test_one_shot_iterables(self):
        out = export_csv(
            ({"a": i} for i in range(2)), (c for c in ["a"]),
        )
        self.assertEqual(out, "a\r\n0\r\n1\r\n")

    def test_ignores_unselected_fields(self):
        out = export_csv([{"a": 1, "zzz": "no"}], ["a"])
        self.assertEqual(out, "a\r\n1\r\n")

    def test_duplicate_columns_rejected(self):
        with self.assertRaises(ValueError):
            export_csv([{"a": 1}], ["a", "a"])

    def test_non_string_columns_rejected(self):
        with self.assertRaises(ValueError):
            export_csv([{"1": 1}], [1])

    def test_does_not_mutate_inputs(self):
        rows = [{"a": 1, "b": 2}]
        cols = ["a", "b"]
        export_csv(rows, cols)
        self.assertEqual(rows, [{"a": 1, "b": 2}])
        self.assertEqual(cols, ["a", "b"])


if __name__ == "__main__":
    unittest.main()

